namespace Custom_nodes {

// Scene "main": graph of "player-1" (object 0)
class FlowGraphScript_0_0 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      objOut2 = -1;
    }
    frame++;
    if (ctx.engine->pad.getClicked().Cross) {
      // node 2 (custom:nearest-visible)
      {
        const float num[4] = {0.0F, 0.0F, 0.0F, 0.0F};
        FlowNodeIO io;
        io.self = 0;
        io.object = 0;
        io.num = num;
        io.str = "";
        flowNearestVisible(ctx, io);
        objOut2 = io.objectOut;
      }
      if (objOut2 >= 0 && objOut2 < ctx.objectCount) {
      ctx.objects[objOut2].visible = false;
      }
    }
    if (ctx.engine->pad.getClicked().Square) {
      // node 5 (custom:spin)
      ctx.objects[2].data.rotation[1] += 45.0F;
      ctx.objects[2].dirty = true;
    }
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  int objOut2 = -1;
};

}  // namespace Custom_nodes

TYRA_SCRIPT(Custom_nodes::FlowGraphScript_0_0);
